targetScope = 'subscription'

param location string = 'westeurope'
param costCenter string = 'platform-engineering'

resource rg 'Microsoft.Resources/resourceGroups@2024-03-01' = {
  name: 'rg-academy-prod'
  location: location
  tags: {
    costCenter: costCenter
    environment: 'prod'
  }
}

@description('Object (principal) ID of the managed identity.')
param principalId string

var readerRoleId = subscriptionResourceId('Microsoft.Authorization/roleDefinitions', 'acdd72a7-3385-48ef-bd42-f606fba81ae7')

resource readerAssignment 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  name: guid(resourceGroup().id, principalId, readerRoleId)
  properties: {
    principalId: principalId
    roleDefinitionId: readerRoleId
    principalType: 'ServicePrincipal'
  }
}

targetScope = 'subscription'

resource requireCostCenter 'Microsoft.Authorization/policyDefinitions@2021-06-01' = {
  name: 'require-costcenter-tag-on-rg'
  properties: {
    policyType: 'Custom'
    mode: 'All'
    displayName: 'Require costCenter tag on resource groups'
    parameters: {
      effect: {
        type: 'String'
        allowedValues: [
          'Audit'
          'Deny'
          'Disabled'
        ]
        defaultValue: 'Audit'
      }
    }
    policyRule: {
      if: {
        allOf: [
          {
            field: 'type'
            equals: 'Microsoft.Resources/subscriptions/resourceGroups'
          }
          {
            field: 'tags[costCenter]'
            exists: 'false'
          }
        ]
      }
      then: {
        effect: '[parameters(\'effect\')]'
      }
    }
  }
}
